def task():
    from transformers import pipeline
    from datasets import load_dataset

    # Load a small public dataset with text data
    # Using the AG News dataset (news classification) which has similar structure
    dataset = load_dataset('ag_news', split='test[:100]')

    # Initialize the text classification pipeline
    # Using a smaller, CPU-friendly model for multilabel classification
    classifier = pipeline(
        'text-classification',
        model='Talip7/scikit-learn-multilabel-classifier',
        return_all_scores=True
    )

    results = []

    # Process first 5 samples from the dataset
    for i, sample in enumerate(dataset):
        if i >= 5:
            break

        text = sample['text'][:200]  # Truncate to first 200 chars

        try:
            outputs = classifier(text)

            # Extract labels with score > 0.5
            labels = [o['label'] for o in outputs[0] if o['score'] > 0.5]

            results.append({
                'text_preview': text[:100],
                'labels': labels,
                'scores': [o['score'] for o in outputs[0]]
            })
        except Exception as e:
            results.append({
                'text_preview': text[:100],
                'error': str(e)
            })

    # Return summary
    return {
        'total_samples_processed': len(results),
        'samples': results,
        'summary': 'Text classification with multilabel detection completed'
    }

