def task():
    import pandas as pd
    import numpy as np
    from sklearn.metrics.pairwise import cosine_similarity
    from sklearn.preprocessing import StandardScaler
    import os

    # Reuse cached dataset
    scratch_dir = '/tmp/readie_session_state'
    data_path = os.path.join(scratch_dir, 'ml_ratings.csv')

    ratings = pd.read_csv(data_path, nrows=5000)

    # Build user-item matrix with proper handling of sparsity
    user_item = ratings.pivot_table(index='userId', columns='movieId', values='rating', fill_value=0)

    target_user = 1

    # Check if target user exists and has ratings
    if target_user not in user_item.index:
        return {'error': f'user {target_user} not found', 'recommendations': []}

    target_vector = user_item.loc[target_user].values.reshape(1, -1)
    if np.sum(target_vector) == 0:
        return {'error': f'user {target_user} has no ratings', 'recommendations': []}

    # Hybrid approach: combine user similarity and item similarity
    # User-user similarity
    user_sim = cosine_similarity(user_item)
    user_sim_df = pd.DataFrame(user_sim, index=user_item.index, columns=user_item.index)

    # Item-item similarity
    item_sim = cosine_similarity(user_item.T)
    item_sim_df = pd.DataFrame(item_sim, index=user_item.columns, columns=user_item.columns)

    # Movies target user hasn't rated
    unrated_mask = user_item.loc[target_user] == 0
    unrated_movies = unrated_mask[unrated_mask].index.tolist()

    if not unrated_movies:
        return {'error': 'user has rated all available movies', 'recommendations': []}

    scores = {}

    # Collaborative filtering: weighted average from similar users
    similar_users = user_sim_df[target_user].nlargest(6)[1:].index.tolist()
    cf_scores = {}
    for movie in unrated_movies:
        weighted_ratings = []
        for sim_user in similar_users:
            if user_item.loc[sim_user, movie] > 0:
                weighted_ratings.append(
                    user_item.loc[sim_user, movie] * user_sim_df.loc[target_user, sim_user]
                )
        if weighted_ratings:
            cf_scores[movie] = np.mean(weighted_ratings)

    # Content-based: similarity to highly-rated items
    user_high_rated = user_item.loc[target_user][user_item.loc[target_user] >= 3].index.tolist()
    cb_scores = {}
    for movie in unrated_movies:
        if user_high_rated:
            similarities = [item_sim_df.loc[movie, rated] for rated in user_high_rated]
            cb_scores[movie] = np.mean(similarities)

    # Combine scores (hybrid)
    for movie in unrated_movies:
        cf_score = cf_scores.get(movie, 0)
        cb_score = cb_scores.get(movie, 0)
        # Weighted average: 60% CF, 40% CB
        scores[movie] = 0.6 * cf_score + 0.4 * cb_score

    if not scores:
        return {'error': 'unable to compute recommendations', 'recommendations': []}

    top_n = sorted(scores.items(), key=lambda x: x[1], reverse=True)[:5]

    return {
        'method': 'hybrid_cf_cb',
        'user_id': target_user,
        'cf_candidates': len(cf_scores),
        'cb_candidates': len(cb_scores),
        'recommendations': [int(m) for m, s in top_n],
        'scores': [float(s) for m, s in top_n]
    }

