            matrix.at[idx, 'item_shop_last_sale'] = int(row['date_block_num']) - int(last_date_block_num)
            cache[key] = row['date_block_num']
    matrix.to_csv('/tmp/readie_session_state/matrix.csv', index=False)
    return 'item_shop_last_sale computed'

